15	// 9323:106685), all four show the link's own text as literally "Wishlist". Message id and the
16	// `moveToWishlist` key are internal identifiers, not user-facing copy — left unchanged.
17	const messages = defineMessages({
18	  remove: { id: 'zimm_cart_item_actions.remove', defaultMessage: 'Remove' },
19	  moveToWishlist: { id: 'zimm_cart_item_actions.move_to_wishlist', defaultMessage: 'Wishlist' },
20	});
