22	export type ZimmCartItemActionsProps = {
23	  /** SFCC product id — the stable identity used to match a resumed pending intent across an auth
24	   *  step, including across a basket merge. See `usePendingWishlistItem`'s own doc for why this
25	   *  is `productId`, not the line's `itemId`. */
26	  productId: string;
27	  /** Interpolated into the wishlist-success toast copy (`useCartMessages.notifyAddedToWishlist`)
28	   *  — never hardcoded at a call site. */
29	  productName: string;
30	  /**
31	   * Whether the current shopper is unauthenticated. Read once by the caller (e.g. from
32	   * `useCustomerType()`) and passed down as a plain prop, rather than this component calling
33	   * that hook itself — see this file's own architecture note below for why.
34	   */
35	  isGuest: boolean;
36	  /**
37	   * Removes this entire line (all units) from the cart — a single call, never looped, regardless
38	   * of the line's current quantity (SFCC-270 AC8 / SFCC-272 AC3). The actual SFCC
39	   * `removeItemFromBasket` call is the caller's own responsibility (SFCC-11 plan step 4.6,
40	   * `cartDrawerContainer.tsx`, not built yet) — this component only ever calls this prop once per
41	   * click, and again (at most once) if a wishlist move succeeds.
42	   */
43	  onRemove: () => void | Promise<void>;
44	  /**
45	   * Attempts the real wishlist-add for an authenticated shopper. The actual SDK call is the
46	   * caller's own responsibility (step 4.6) — this component only calls it and reacts to the
47	   * result. Resolves to a discriminated union so this component can choose the right feedback
48	   * without any data-fetching of its own — see `WishlistMoveResult`'s own doc.
49	   */
50	  onMoveToWishlist: () => Promise<WishlistMoveResult>;
51	  /**
52	   * Called when a guest clicks "Wishlist" for this row, after the pending intent has
53	   * already been persisted (see `usePendingWishlistItem`). The caller is responsible for opening
54	   * the one shared wishlist auth drawer — see this file's own architecture note for why this
55	   * component does not open it directly.
56	   */
57	  onGuestWishlistClick: () => void;
58	  /**
59	   * 1:1 Figma-alignment audit fix, 2026-09-22: called when `attemptMoveToWishlist` resolves
60	   * `'already-in-wishlist'`, alongside — not instead of — the existing `notifyAlreadyInWishlist()`
61	   * toast below. This component's own result branching is otherwise invisible to its parent: the
62	   * caller owns `ProductItem`'s `message` slot (cart-line inline status, SFCC-795 §11.2) and needs
63	   * to know this specific line just got this result to show it there. Optional so every existing
64	   * caller from before this prop existed keeps working unchanged, with only the toast firing.
65	   */
66	  onAlreadyInWishlist?: () => void;
67	};
68	
69	/**
70	 * Molecule — the "Remove" / "Wishlist" action links rendered below a cart line's quantity
71	 * stepper (SFCC-270 AC8, SFCC-272). Supplied by the caller into base `product-item`'s own
72	 * `secondaryActions` slot (already wired, `overrides/app/components/product-item/index.tsx:365`)
73	 * — this molecule does not inject itself into that structure, it is simply the node passed in.
74	 *
75	 * Architecture note — why this component does not call `useWishlistAuthDrawer` itself, despite
76	 * that hook being an auth-gating hook rather than a data-fetching one (so calling it from a
77	 * `ui-kits/` component is not, by itself, a `components.md` container/presentational violation —
78	 * `ZimmWishlistAuthDrawer`, `overrides/app/components/ui-kits/organisms/zimmWishlistAuthDrawer/
79	 * index.tsx:35-58`, is the existing precedent for exactly that). The SFCC-11 plan requires exactly
80	 * ONE `useWishlistAuthDrawer` instance for the whole cart (`intentId: 'cart-wishlist'`), and
81	 * explicitly rejects mounting one instance per line item — a multi-item bag would mount a
82	 * `useForm`, three `useAuthHelper`s, a `useAuthModal` and a drawer per row. Because this component
83	 * is itself rendered once per cart line (one per `secondaryActions` slot), calling that hook
84	 * directly here would reproduce exactly the rejected per-row shape. So the one real hook instance
85	 * must live above every row — the cart container, SFCC-11 plan step 4.6, not yet built — and this
86	 * component receives `isGuest` / `onGuestWishlistClick` as plain props instead, wired by that
87	 * container to its own single hoisted `handleTriggerClick`. `useCartMessages` below has no such
88	 * constraint: it is a stateless wrapper around Chakra's own `useToast()`
89	 * (`overrides/app/hooks/useCartMessages.ts`), safe to call from as many rendered instances as
90	 * there are cart lines — this divergence from a literal per-row hook call is deliberate and
91	 * disclosed in this step's own report, not silently resolved.
92	 *
93	 * @param props see ZimmCartItemActionsProps
94	 */
95	export const ZimmCartItemActions = ({
96	  productId,
97	  productName,
98	  isGuest,
99	  onRemove,
100	  onMoveToWishlist,
101	  onGuestWishlistClick,
102	  onAlreadyInWishlist,
103	}: ZimmCartItemActionsProps) => {
104	  const intl = useIntl();
105	  const styles = useStyleConfig(ZIMM_CART_ITEM_ACTIONS_RECIPE);
106	  const { notifyAddedToWishlist, notifyAlreadyInWishlist } = useCartMessages();
107	
108	  // Shared by both the direct (already-authenticated) click path below and the post-auth resume
109	  // path (usePendingWishlistItem's onResume) — one implementation of "branch on the move result",
110	  // not two copies of the same logic.
111	  const attemptMoveToWishlist = useCallback(async () => {
112	    const result = await onMoveToWishlist();
113	    if (result.status === 'success') {
114	      await onRemove();
115	      notifyAddedToWishlist(productName);
116	    } else if (result.status === 'already-in-wishlist') {
117	      notifyAlreadyInWishlist();
118	      onAlreadyInWishlist?.();
119	    }
120	    // 'error': no AC or Figma copy exists for this branch — leave the item in the cart and emit
121	    // no message rather than invent feedback text (same "do not invent copy" principle the
122	    // SFCC-11 plan applies to its own unspecified error feedback elsewhere, e.g. step 5.1).
123	  }, [onMoveToWishlist, onRemove, notifyAddedToWishlist, notifyAlreadyInWishlist, productName, onAlreadyInWishlist]);
124	
125	  const { beginPendingMove } = usePendingWishlistItem({
126	    productId,
127	    isGuest,
128	    onResume: attemptMoveToWishlist,
129	  });
130	
131	  const handleWishlistClick = () => {
132	    if (isGuest) {
133	      beginPendingMove();
134	      onGuestWishlistClick();
135	      return;
136	    }
137	    void attemptMoveToWishlist();
138	  };
139	
140	  return (
141	    <chakra.div __css={styles}>
142	      <ZimmLink size="small" label={intl.formatMessage(messages.remove)} onClick={() => void onRemove()} />
143	      <ZimmLink size="small" label={intl.formatMessage(messages.moveToWishlist)} onClick={handleWishlistClick} />
144	    </chakra.div>
145	  );
146	};
